import{_ as i,D as s,c as l,I as t,j as e,a,a4 as o,o as d}from"./chunks/framework.CRCV4hx_.js";const E=JSON.parse('{"title":"Reservations","description":"","frontmatter":{},"headers":[],"relativePath":"reservations.md","filePath":"reservations.md"}'),h={name:"reservations.md"},c=e("h1",{id:"reservations",tabindex:"-1"},[a("Reservations "),e("a",{class:"header-anchor",href:"#reservations","aria-label":'Permalink to "Reservations"'},"​")],-1),u=e("p",null,"Resrv offers various ways to list and manage your reservations inside Statamic's Control Panel. In this page, we'll go through the available tools and how to use them.",-1),p=e("h2",{id:"reservation-list",tabindex:"-1"},[a("Reservation List "),e("a",{class:"header-anchor",href:"#reservation-list","aria-label":'Permalink to "Reservation List"'},"​")],-1),g=e("p",null,"The Reservations section in the Control Panel allows you to list and filter all your reservations.",-1),m=o('<p>Here, you can filter and reorder all your reservations by the <em>Entry</em> they belong to, the <em>status</em> of the reservation, the reservation <em>start date</em> or <em>made date</em> (when the booking was created), and the <em>year</em>.</p><div class="tip custom-block"><p class="custom-block-title">Default status filter</p><p>The Status filter defaults to <strong>Confirmed</strong> and <strong>Partner</strong>, so pending and expired reservations are hidden until you opt them in. If you &quot;don&#39;t see your expired reservations&quot;, this is why. Just enable those statuses in the filter.</p></div><p>The status of a reservation can be one of the following:</p><ul><li><strong>Confirmed</strong>: The reservation is confirmed and paid for.</li><li><strong>Pending</strong>: The user has started the checkout process but hasn&#39;t completed it. A pending reservation still holds availability.</li><li><strong>Refunded</strong>: The reservation has been refunded. This is a terminal status.</li><li><strong>Expired</strong>: The user started the reservation but never finished the checkout. Availability is restored.</li><li><strong>Partner</strong>: This special status means a reservation was made through an affiliate, skipping payment. It is treated as a confirmed booking for reports and the calendar.</li></ul><h2 id="how-reservations-work" tabindex="-1">How reservations work <a class="header-anchor" href="#how-reservations-work" aria-label="Permalink to &quot;How reservations work&quot;">​</a></h2><p>Sometimes there can be confusion due to many expired reservations being displayed. This is totally normal and by design, as a new reservation is created the moment the user starts the checkout process. This also plays a part in the availability system, reducing availability to prevent double bookings.</p><p>If a reservation is expired, it means that a user started the checkout process but never completed it. By default, the system &quot;holds&quot; a reservation for 10 minutes, but you can change that in the <a href="./configuration#checkout">configuration</a> using the &quot;Minutes to hold&quot; setting. If personal details were added, the user stopped the checkout process before payment. Otherwise, they likely never intended to complete the process in the first place.</p><h2 id="reservation-details" tabindex="-1">Reservation Details <a class="header-anchor" href="#reservation-details" aria-label="Permalink to &quot;Reservation Details&quot;">​</a></h2><p>Clicking on the status of a reservation in the Reservations list will take you to the Reservation Details page. Here, you can view all reservation details, the data the customer provided during checkout, any extras or options, the dynamic pricing policies that were applied, and the payment information.</p>',9),v=o('<p>The details page surfaces:</p><ul><li>The <strong>rate</strong> used for the booking. For multi-rate bookings, each child reservation is listed with its own rate (see <a href="./rates">Rates</a>).</li><li>The <strong>payment gateway</strong> the reservation was paid with, plus a per-gateway <strong>surcharge</strong> line when a surcharge applies (see <a href="./payment-gateways">Payment gateways</a>).</li></ul><h2 id="refunds" tabindex="-1">Refunds <a class="header-anchor" href="#refunds" aria-label="Permalink to &quot;Refunds&quot;">​</a></h2><p>From the item menu in the Reservation List, you can refund a reservation:</p>',4),f=o('<p>After confirmation, the reservation is marked as refunded and the customer receives a notification email. <strong>Availability is also restored.</strong></p><p>The refund routes through whichever payment gateway the reservation was originally paid with. With multiple gateways configured, Resrv resolves the correct one per reservation, so a booking paid with Stripe refunds through Stripe and a booking paid with another gateway refunds through that gateway.</p><p><strong>Partner and zero-payment reservations</strong> skip the gateway call entirely. Because no charge was ever taken (an affiliate skip-payment or a fully-discounted booking never created a payment intent), the reservation is simply marked refunded and its availability restored: no gateway is contacted.</p><p>If you build a <a href="./custom-payment-gateway">custom payment gateway</a>, implement the <code>refund()</code> method on the <code>PaymentInterface</code> contract so refunds initiated from the Control Panel reach your provider.</p><h2 id="reservations-calendar" tabindex="-1">Reservations Calendar <a class="header-anchor" href="#reservations-calendar" aria-label="Permalink to &quot;Reservations Calendar&quot;">​</a></h2><p>Another helpful view is the Reservation Calendar. This view allows you to see all <strong>confirmed and partner</strong> reservations on a calendar:</p>',6),_=e("p",null,"Clicking on a reservation will take you to the Reservation Details page.",-1),y=e("h2",{id:"reports",tabindex:"-1"},[a("Reports "),e("a",{class:"header-anchor",href:"#reports","aria-label":'Permalink to "Reports"'},"​")],-1),b=e("p",null,"You can create some basic reports to see how your sales are performing.",-1),w=o("<p>A <strong>Filter by</strong> toggle lets you choose how the date range is applied:</p><ul><li><strong>Reservation date</strong>: filters by each booking&#39;s start date (<code>date_start</code>).</li><li><strong>Date created</strong>: filters by when the reservation was made (<code>created_at</code>).</li></ul><p>Pick a date range alongside it, and the report covers all <strong>confirmed and partner</strong> reservations within that range. Reports surface:</p><ul><li>Three summary cards: <strong>Reservations</strong> (count), <strong>Revenue</strong> (total), and <strong>Average reservation value</strong>.</li><li>A <strong>Best sellers</strong> panel: your top entries by reservation count, with revenue and share.</li><li>A <strong>Top selling extras</strong> panel: your most-booked extras.</li></ul>",4),k={id:"export",tabindex:"-1"},T=e("a",{class:"header-anchor",href:"#export","aria-label":'Permalink to "Export <Badge type="tip" text="NEW" />"'},"​",-1),x=e("p",null,[a("The "),e("strong",null,"Export"),a(" section lets you export reservations to a CSV file. It's a separate Control Panel page with its own filters and column picker.")],-1),P=o('<h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><ul><li><strong>Reservation date range</strong>: filters by each booking&#39;s start date (<code>date_start</code>), not the created date. Defaults to the last 30 days.</li><li><strong>Status</strong>: a checkbox group that defaults to <strong>Confirmed</strong> and <strong>Partner</strong>.</li><li><strong>Item</strong>: restrict the export to a single entry.</li><li><strong>Affiliate</strong>: restrict the export to a single affiliate (shown only when affiliates exist).</li><li><strong>Only include reservations with customer details</strong>: limits the export to bookings that have customer data attached.</li></ul><h3 id="column-picker" tabindex="-1">Column picker <a class="header-anchor" href="#column-picker" aria-label="Permalink to &quot;Column picker&quot;">​</a></h3><p>Choose exactly which columns to include. Fields are organized into groups (Reservation, Pricing, Customer, Entry, Add-ons), each with an All / None toggle. The default selection covers reference, status, item, rate, quantity, start and end dates, created date, customer email, and total.</p><p>Your selection is remembered in the browser for next time.</p><div class="tip custom-block"><p class="custom-block-title">Custom checkout fields</p><p>Any custom checkout fields you&#39;ve added are auto-discovered from stored customer data and appear in the column picker automatically, labeled from the field&#39;s display name. So a site&#39;s custom fields become exportable columns without any configuration.</p></div><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h3><p>A live <strong>match count</strong> updates as you change the filters, so you can see how many reservations will be exported before downloading. The <strong>Download CSV</strong> button is enabled once the count is above zero and you have a date range, at least one status, and at least one field selected.</p><p>The file is a UTF-8 CSV downloaded as <code>reservations-Y-m-d-His.csv</code> (e.g. <code>reservations-2026-06-08-143015.csv</code>). Large exports are streamed safely in batches, and string values that could be interpreted as spreadsheet formulas are escaped to guard against CSV injection.</p>',9);function C(R,A,S,I,q,V){const r=s("Image"),n=s("Badge");return d(),l("div",null,[c,u,p,g,t(r,{src:"./img/resrv-reservations.webp",alt:"The Reservations section in the Control Panel."}),m,t(r,{src:"./img/resrv-reservation-details.webp",alt:"A totally random reservation by a random user."}),v,t(r,{src:"./img/resrv-reservation-refund.webp",alt:"How to refund a reservation."}),f,t(r,{src:"./img/resrv-reservation-calendar.webp",alt:"The Reservation Calendar."}),_,y,b,t(r,{src:"./img/resrv-reservation-reports.webp",alt:"The reports page in the Control Panel."}),w,e("h2",k,[a("Export "),t(n,{type:"tip",text:"NEW"}),a(),T]),x,t(r,{src:"./img/resrv-reservations-export.webp",alt:"The reservations CSV export page in the Control Panel."}),P])}const N=i(h,[["render",C]]);export{E as __pageData,N as default};
